default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ldap' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('LDAPClientIntegrity', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_ldap_client_integrity)) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Services\Ldap [LDAPClientIntegrity]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ldap')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Ldap' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\Ldap' -Name 'LDAPClientIntegrity' -Value $ODV_ldap_client_integrity -PropertyType DWord -Force | Out-Null
exit 0
